.message-header {
  margin-left: calc(clamp(96px, 27vw, 150px) + 12px) !important;
  margin-bottom: 6px !important;
  height: 30px !important;
  min-height: 30px !important;
  box-sizing: border-box !important;
  padding-top: 0px !important;
  padding-bottom: 4px !important;
  padding-left: 0px !important;
  align-items: center !important;
  border-bottom: 1px solid hsl(var(--primary) / 0.2) !important;
}

.message-header-info {
  margin-left: 0px !important;
  padding-left: 0px !important;
  flex-wrap: nowrap !important;
  white-space: nowrap !important;
  align-items: center !important;
}

.message-username {
  font-family: "Orbitron", "Exo 2", Arial, sans-serif !important;
  font-weight: 700 !important;
  font-size: 1.02em !important;
  letter-spacing: 0.14em !important;
  text-transform: uppercase !important;
  line-height: 1.2 !important;
  display: inline-block !important;
  margin-left: 0px !important;
  margin-right: 8px !important;
  padding: 0px !important;
  text-shadow: none !important;
  animation: nameShimmer 8s ease-in-out infinite !important;
  color: transparent !important;
  background-image: linear-gradient(100deg, hsl(var(--star, 210 100% 92%)) 0%, hsl(var(--primary)) 25%, hsl(var(--nebula, 265 55% 72%)) 50%, hsl(var(--primary)) 75%, hsl(var(--star, 210 100% 92%)) 100%) !important;
  background-size: 200% 100% !important;
  background-clip: text !important;
}

.message-timestamp {
  font-size: 0.72em !important;
  opacity: 0.55 !important;
  color: hsl(var(--muted-foreground)) !important;
  letter-spacing: 0.04em !important;
  transition: opacity 0.25s ease, color 0.25s ease !important;
}

.message-container:hover .message-timestamp {
  opacity: 1 !important;
  color: hsl(var(--primary)) !important;
}

.message-model {
  font-family: var(--font-mono);
  font-size: 0.68em;
  letter-spacing: 0.05em;
  color: hsl(var(--muted-foreground));
  background: hsl(217 55% 13% / 0.6);
  border: 1px solid hsl(var(--primary) / 0.25);
  border-radius: 0px;
  padding: 1px 8px;
  transition: border-color 0.25s ease, color 0.25s ease;
}

.message-model:hover {
  border-color: hsl(var(--primary) / 0.55);
  color: hsl(var(--foreground));
}

.message-index {
  font-family: var(--font-mono);
  font-size: 0.7em;
  opacity: 0.55;
}

.message-actions {
  opacity: 0.15;
  transition: opacity 0.25s ease, transform 0.25s ease;
}

.message-container:hover .message-actions {
  opacity: 1;
  transform: translateY(-1px);
}

.swipe-counter {
  font-family: var(--font-mono);
  font-size: 0.7em;
  color: hsl(var(--muted-foreground));
  background: hsl(217 55% 13% / 0.55);
  border: 1px solid hsl(var(--primary) / 0.2);
  border-radius: 0px;
  padding: 1px 7px;
  transition: border-color 0.25s ease;
}

.message-header + .message-body .message-avatar {
  margin-top: -32px !important;
}

/* ===== KEYFRAMES ===== */
@keyframes jellyfishPulse {
  0%, 100% { text-shadow: 0 0 6px hsl(var(--primary) / 0.4), 0 0 14px hsl(var(--primary) / 0.2); }
  50%      { text-shadow: 0 0 10px hsl(var(--primary) / 0.6), 0 0 24px hsl(var(--primary) / 0.35); }
}

@keyframes usernameGlow {
  0%, 100% { text-shadow: 0 0 4px hsl(var(--primary) / 0.3); }
  50%      { text-shadow: 0 0 12px hsl(var(--primary) / 0.65), 0 0 2px hsl(var(--primary) / 0.5); }
}

@keyframes riseIn {
  0%   { opacity: 0; transform: translateY(8px); }
  100% { opacity: 1; transform: translateY(0); }
}

/* ===== SHARED: crisp edges (no rounding anywhere) ===== */
.message-container,
.message-content,
.message-avatar {
  border-radius: 0 !important;
}

/* ===== MESSAGE CONTAINER: subtle jellyfish bell edge glow ===== */
.message-container {
  border: none !important;
  background-color: transparent !important;
  background-image: none !important;
  box-shadow: 0 0 15px hsl(var(--primary) / 0.04), 0 0 2px hsl(var(--primary) / 0.1) !important;
  padding: 0 4px !important;
  margin-bottom: 6px !important;
  animation: riseIn 0.4s ease-out 1 backwards !important;
}

.message-container:hover {
  background-color: hsl(var(--primary) / 0.03) !important;
}

/* ===== MESSAGE BUBBLE ===== */
.message-content {
  background-color: hsl(var(--card) / 0.4) !important;
  border: 1px solid hsl(var(--border) / 0.5) !important;
  padding: 10px 12px !important;
  line-height: 1.6 !important;
  box-shadow: 0 0 15px hsl(var(--primary) / 0.04), 0 0 2px hsl(var(--primary) / 0.1) !important;
  text-shadow: 0 0 1px hsl(var(--foreground) / 0.15) !important;
  transition: box-shadow 0.3s ease, transform 0.3s ease !important;
}

.message-content:hover {
  box-shadow: 0 0 25px hsl(var(--primary) / 0.1), 0 0 4px hsl(var(--primary) / 0.2) !important;
  transform: translateY(-1px) !important;
}

/* ===== BLOCKQUOTES: bioluminescent jellyfish pulse ===== */
.message-content blockquote {
  border-left: 2px solid hsl(var(--primary) / 0.45) !important;
  padding-left: 1rem !important;
  text-shadow: 0 0 8px hsl(var(--primary) / 0.5), 0 0 20px hsl(var(--primary) / 0.25) !important;
  animation: jellyfishPulse 3s ease-in-out infinite !important;
}

.message-content blockquote:hover {
  animation: none !important;
  text-shadow: 0 0 12px hsl(var(--primary) / 0.75), 0 0 32px hsl(var(--primary) / 0.4), 0 0 56px hsl(var(--primary) / 0.15) !important;
}

/* ===== EMPHASIS: shared bioluminescent blue ===== */
.message-content i,
.message-content em,
.message-content b,
.message-content strong {
  color: hsl(var(--primary)) !important;
}

.message-content i,
.message-content em {
  font-style: italic !important;
  text-shadow: 0 0 6px hsl(var(--primary) / 0.35) !important;
}

.message-content b,
.message-content strong {
  font-weight: 800 !important;
  text-shadow: 0 0 10px hsl(var(--primary) / 0.55), 0 0 2px hsl(var(--primary) / 0.4) !important;
}

/* ===== HEADER ROW ===== */
.message-header {
  margin-bottom: 4px !important;
  padding-bottom: 3px !important;
  padding-left: 10px !important;
  border-bottom: 1px solid hsl(var(--primary) / 0.2) !important;
}

.message-username {
  color: hsl(var(--primary)) !important;
  font-weight: 700 !important;
  letter-spacing: 0.03em !important;
  display: inline-block !important;
  animation: usernameGlow 4s ease-in-out infinite !important;
}

.message-timestamp {
  font-size: 0.72em !important;
  opacity: 0.5 !important;
  color: hsl(var(--muted-foreground)) !important;
  transition: opacity 0.25s ease, color 0.25s ease !important;
}

.message-container:hover .message-timestamp {
  opacity: 1 !important;
  color: hsl(var(--primary)) !important;
}

/* ===== AVATAR ===== */
.message-avatar {
  transition: transform 0.3s ease, filter 0.3s ease !important;
}

.message-container:hover .message-avatar {
  transform: scale(1.05) !important;
  filter: brightness(1.15) !important;
}

/* ===== ACTIONS ===== */
.message-actions {
  opacity: 0.15 !important;
  transition: opacity 0.25s ease !important;
}

.message-container:hover .message-actions {
  opacity: 1 !important;
}

